})
"""


class PullError(RuntimeError):
    pass


def pick_option(page, name):
    """Click the dropdown option whose text is exactly `name`."""
    opt = page.get_by_role("option", name=name, exact=True)
    if opt.count() == 0:
        opt = page.locator("[role=option]", has_text=re.compile(rf"^\s*{re.escape(name)}\s*$"))
    if opt.count() == 0:
        raise PullError(f"option not found: {name!r}")
    opt.first.scroll_into_view_if_needed()
    opt.first.click()


def set_select(page, which, value):
    state = tag(page)
    if state.get(which) == value:
        return
    box = page.locator(f"[data-tp={which}]")
    if box.count() == 0:
        raise PullError(f"{which} box not found (run --probe)")
    box.first.click()
    box.first.fill("")
    box.first.type(value, delay=30)
    time.sleep(0.8)
    pick_option(page, value)
    settle(page)
    got = tag(page).get(which)
    if got != value:
        raise PullError(f"{which} reads {got!r} after selecting {value!r}")


def set_scope(page, scope):
    state = tag(page)
    if state.get("scopes") == [scope]:
        return
    box = page.locator("[data-tp=scope]")
    if box.count() == 0:
        raise PullError("scope box not found (run --probe)")
    box.first.click()
    time.sleep(0.8)
    # Untick every selected option except the wanted one ("Clear" does not remove Power Four).
    for _ in range(6):
        selected = page.locator("[role=option][aria-selected=true], [role=option][data-checked=true]")
        names = [selected.nth(i).inner_text().strip() for i in range(selected.count())]
        extra = [n for n in names if n != scope]
        if not extra:
            break
        pick_option(page, extra[0])
        time.sleep(0.6)
    if scope not in tag(page).get("scopes", []):
        box.first.type(scope, delay=30)
        time.sleep(0.8)
        pick_option(page, scope)
    page.keyboard.press("Escape")
    settle(page)
    got = tag(page).get("scopes")
    if got != [scope]:
        raise PullError(f"scope reads {got} after selecting {scope!r}")


def download_csv(page, dest):
    tag(page)
    more = page.locator("[data-tp=more]")
    if more.count() == 0:
        more = page.get_by_role("button", name=re.compile("more options", re.I))
    if more.count() == 0:
        raise PullError("More options button not found (run --probe)")
    more.last.click()
    time.sleep(0.8)
    item = page.get_by_role("menuitem", name=re.compile("download csv", re.I))
    if item.count() == 0:
        item = page.get_by_text(re.compile(r"^\s*Download CSV\s*$", re.I))
    with page.expect_download(timeout=60000) as dl:
        item.first.click()
    dl.value.save_as(str(dest))


